        index = buildLinkIndex(readSpecFiles(specsRoot, roots));
        indexCache.set(key, index);
    }
    return index;
}
/** The base identifier of a (possibly chained) callee — `it` in `it.each([])(…)`. */
function rootCallName(callee) {
    let node = callee;
