1	/**
2	 * status-coverage — the pure core behind `require-status-matches-coverage`.
3	 *
4	 * The coverage math itself (`statementCoverage` -> `coverageTier` ->
5	 * `expectedStatus`) lives in `@re-cinq/lore-shared` because spec-status-upkeep
6	 * FR1 opens the PR that fixes what this rule reports, and the two must agree on
7	 * what a doc's links entitle it to claim. What is rule-specific — comparing that
8	 * against the declared status, and locating the row a human has to edit — lives
9	 * here.
10	 *
11	 * Split out of the rule so it is testable without a RuleTester.
12	 */
13	import { coverageTier, expectedStatus, parseDocStatus, statementCoverage, statusTier, } from "./spec-parsers.mjs";
14	/**
15	 * @typedef {{ reason: "untagged", line: number }} UntaggedMismatch
16	 * @typedef {{ reason: "tier", expected: string, actual: string, testable: number, linked: number, line: number }} TierMismatch
17	 */
18	/**
19	 * 1-based line of the doc's declared status, so a report anchors on the cell a
20	 * human has to edit. Mirrors the source shapes `parseDocStatus` reads — a spec's
21	 * `| Status | <value> |` table row, an ADR's frontmatter `status:` — including
22	 * its first-match-wins rule (several API-route specs carry a second
23	 * `| Status | Body |` table documenting HTTP codes; the header row wins).
24	 *
25	 * @returns {number | null} null when the doc declares no status at all
26	 */
27	function statusLine(content, kind) {
28	    const lines = content.split(/\r?\n/);
29	    if (kind === "spec") {
30	        const index = lines.findIndex((line) => {
31	            const cells = line.split("|").map((cell) => cell.trim());
32	            return cells.length >= 3 && cells[1].toLowerCase() === "status";
33	        });
34	        return index === -1 ? null : index + 1;
35	    }
36	    if (!/^---\r?\n([\s\S]*?)\r?\n---/.test(content)) {
37	        return null;
38	    }
39	    const index = lines.findIndex((line) => /^status\s*:\s*(.+?)\s*$/i.test(line));
40	    return index === -1 ? null : index + 1;
41	}
42	/**
43	 * @param {string} content markdown body of a spec.md / ADR file
44	 * @param {"spec" | "adr"} kind
45	 * @returns {UntaggedMismatch | TierMismatch | null} null when the doc is consistent or skipped
46	 */
